export type GetHomepageBannersParams = {
  /**
 * ISO 3166-1 alpha-2 country code (case-insensitive) used to filter
country-targeted banners. Wildcard "*" or omission returns only
the global ("*") banners.

 */
  countryCode?: string;
};

export type GetHomepageCategoriesParams = {
  /**
 * ISO 3166-1 alpha-2 country code (case-insensitive) used to
resolve which WooCommerce store the categories are sourced
from. When omitted, the server falls back to Lebanon.

 */
  countryCode?: string;
  /**
 * City identifier (e.g. "ae-dubai", "ae-abu-dhabi") used to
resolve a city-specific WooCommerce store when the country
alone is ambiguous.

 */
  cityId?: string;
};

export type GetHomepageBestSellersParams = {
  /**
   * ISO 3166-1 alpha-2 country code (case-insensitive) used to filter products by deliverable country.
   */
  countryCode?: string;
  /**
   * City identifier (e.g. "ae-dubai") used to filter products by deliverable city.
   */
  cityId?: string;
  /**
   * Language code ("en", "ar", or "fr"). Reserved for future localisation.
   */
  lang?: string;
};

export type GetDeliveryConfigParams = {
  /**
   * ISO 3166-1 alpha-2 country code (case-insensitive).
   */
  countryCode?: string;
  /**
   * Optional city id from /delivery-locations.
   */
  cityId?: string;
};

export type GetGeoCurrencyByCoordsParams = {
  /**
   * WGS84 latitude in decimal degrees, range -90..90.
   */
  lat: number;
  /**
   * WGS84 longitude in decimal degrees, range -180..180.
   */
  lng: number;
};

export type WooSearchParams = {
  /**
   * Search query string (2–100 characters).
   * @minLength 2
   * @maxLength 100
   */
  q: string;
  countryCode?: string;
  cityId?: string;
  lang?: string;
};
